import datetime
from decimal import Decimal
from django.core.management.base import BaseCommand
from destinations.models import District, Category, Destination, DestinationImage
from core.models import VerificationStatus


class Command(BaseCommand):
    help = "Idempotently import verified tourist destinations belonging exclusively to Kottayam district."

    def handle(self, *args, **options):
        self.stdout.write(self.style.NOTICE("Starting Kottayam destinations import..."))

        # 1. Ensure Kottayam District exists
        district, dist_created = District.objects.get_or_create(
            slug="kottayam",
            defaults={
                "name": "Kottayam",
                "headquarters": "Kottayam",
                "description": (
                    "Celebrated as the 'Land of Letters, Latex, and Lakes' (Akshara Nagari), Kottayam spans from the "
                    "tranquil eastern shore of Vembanad Lake and Kumarakom Bird Sanctuary across historic temples, pilgrim "
                    "cathedrals, and India's earliest colleges to dramatic Western Ghats granite summits like Illikkal Kallu, "
                    "Ilaveezhapoonchira, and Marmala Waterfalls."
                ),
                "latitude": Decimal("9.591567"),
                "longitude": Decimal("76.522153"),
                "cover_image_url": "https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1d/Kumarakom_backwaters_panorama.jpg/1280px-Kumarakom_backwaters_panorama.jpg",
                "official_dtpc_website": "https://dtpckottayam.com/",
                "dtpc_contact": "+91 481 2560479 / info@dtpckottayam.com",
                "source_name": "DTPC Kottayam & Department of Tourism, Govt. of Kerala",
                "source_url": "https://kottayam.nic.in/tourism/",
                "verification_status": VerificationStatus.VERIFIED,
                "last_verified_date": datetime.date(2026, 11, 26),
                "valid_until": datetime.date(2027, 11, 26),
                "is_demo": False,
            },
        )
        self.stdout.write(f"District 'Kottayam': {'Created' if dist_created else 'Already exists'}")

        # 2. Ensure Categories exist (matching unified 8 tourism categories)
        categories_data = [
            ("Beaches and Coastal Attractions", "beaches-and-coastal", "bi-water", "Pristine sandy shores, estuaries, lighthouses, and coastal fishing harbours."),
            ("Hill Stations and Nature", "hill-stations-and-nature", "bi-tree", "Western Ghats granite peaks, meadows, plateau viewpoints, and hill estates."),
            ("Waterfalls", "waterfalls", "bi-moisture", "Cascading forest water streams and natural rocky waterfalls."),
            ("Wildlife and Ecotourism", "wildlife-and-ecotourism", "bi-shield-check", "Protected wetland bird sanctuaries, groves, and eco-reserves."),
            ("Dams, Lakes and Backwaters", "dams-lakes-and-backwaters", "bi-tsunami", "Vembanad lagoons, boat jetties, backwater islands, and delta villages."),
            ("Temples and Religious Attractions", "temples-and-religious", "bi-flower1", "Ancient Shiva & Devi temples, Christian pilgrimage shrines, and historic mosques."),
            ("Historical Places and Museums", "historical-places-and-museums", "bi-bank", "Royal palaces, driftwood & heritage museums, memorials, and historic campuses."),
            ("Parks, Culture and Entertainment", "parks-culture-and-entertainment", "bi-stars", "Science parks, civic grounds, cultural festivals, and recreation hubs."),
        ]

        categories_map = {}
        for cat_name, cat_slug, cat_icon, cat_desc in categories_data:
            cat_obj, _ = Category.objects.get_or_create(
                slug=cat_slug,
                defaults={"name": cat_name, "icon": cat_icon, "description": cat_desc},
            )
            categories_map[cat_slug] = cat_obj

